insert into public.mblite_books(id) values ('3det-alpha'),('t20-ameacas'),('t20-atlas'),('t20-herois'),('t20-deuses'),('t20-deuses-menores'),('t20-npcs'),('t20-distincoes'),('3det-alpha-monstros'),('3det-alpha-tormenta'),('3det-victory-grid'),('3det-victory-conversao'),('3det-victory-pelucias'),('t20-kit') on conflict do nothing;
create or replace function mblite_access_private.scope_for(p_book text) returns text language sql immutable set search_path='' as $$ select case when p_book like 'op-%' and p_book<>'op-all' then 'op-all' when p_book in ('t20-jda','t20-ameacas','t20-atlas','t20-herois','t20-deuses','t20-deuses-menores','t20-npcs','t20-distincoes') then 't20-all' when p_book in ('3det-victory','3det-alpha-monstros','3det-alpha-tormenta','3det-victory-grid','3det-victory-conversao','3det-victory-pelucias') then '3det-all' when p_book in ('pf2e-core','pf2e-player-br','pf2e-player-core','pf2e-gm-core') then 'pf2e-all' when p_book in ('dnd-player-2024','dnd-dm-2024','dnd-monsters-2014') then 'dnd-all' else null end $$;
revoke all on function mblite_access_private.scope_for(text) from public,anon,authenticated;